// Generated by npm run build. Do not edit.
// ---- config.js ----
// All gameplay numbers are in game px (640×360 logical resolution).
const GAME_WIDTH = 640;
const GAME_HEIGHT = 360;
const RENDER_SCALE = 3;
const PX_PER_METRE = 10;
const FULL_CHARGE_METRES = 3000;

// Data-driven themes: background, dim colour and dim opacity. Car, rockets and UI are shared.
const THEMES = Object.freeze({
    night: Object.freeze({background: 'bg_starbase_night.webp', dimColor: '#030716', dim: 0.5}),
    dawn: Object.freeze({background: 'bg_starbase_dawn.webp', dimColor: '#160a2a', dim: 0.42}),
    day: Object.freeze({background: 'bg_starbase_day.webp', dimColor: '#0a1c3c', dim: 0.38})
});

// Gaps between rockets at the start speed. They stretch with speed, but less than the speed grows,
// so rockets come more often as the run goes on. Distances (…From) are in metres.
const DIFFICULTY_PRESETS = Object.freeze({
    easy: Object.freeze({minGap: 230, maxGap: 340, missileFrom: 250, gatesFrom: 300, salvosFrom: 900}),
    normal: Object.freeze({minGap: 170, maxGap: 260, missileFrom: 100, gatesFrom: 150, salvosFrom: 500}),
    hard: Object.freeze({minGap: 140, maxGap: 210, missileFrom: 30, gatesFrom: 50, salvosFrom: 250})
});

const DEFAULT_SETTINGS = Object.freeze({
    difficulty: 'normal',
    theme: 'night',
    ...DIFFICULTY_PRESETS.normal,
    debug: false,
    speed: 185,
    maxSpeed: 420,
    acceleration: 5,
    gravity: 1000,
    thrust: 2200,
    maxRise: 260,
    maxFall: 460,
    powerUpMin: 7, // seconds between power-up pickups
    powerUpMax: 13,
    hitboxInset: 2,
    storageKey: 'tesla-joyride-best',
    runsKey: 'tesla-joyride-runs',
    themeKey: 'tesla-joyride-theme'
});

function createSettings(options = {}) {
    const difficulty = options.difficulty ?? DEFAULT_SETTINGS.difficulty;
    const preset = DIFFICULTY_PRESETS[difficulty];

    if (!preset) {
        throw new RangeError('TeslaJoyride option "difficulty" must be easy, normal or hard');
    }

    const settings = {...DEFAULT_SETTINGS, ...preset, ...options, difficulty};

    if (!Object.hasOwn(THEMES, settings.theme)) {
        throw new RangeError(`TeslaJoyride option "theme" must be one of ${Object.keys(THEMES).join(', ')}`);
    }

    for (const name of ['minGap', 'maxGap', 'speed', 'maxSpeed', 'gravity', 'thrust', 'maxRise', 'maxFall', 'powerUpMin', 'powerUpMax']) {
        validatePositiveNumber(name, settings[name]);
    }

    for (const name of ['acceleration', 'missileFrom', 'gatesFrom', 'salvosFrom']) {
        if (!Number.isFinite(settings[name]) || settings[name] < 0) {
            throw new TypeError(`TeslaJoyride option "${name}" must be zero or a finite positive number`);
        }
    }

    if (settings.maxGap < settings.minGap) {
        throw new RangeError('TeslaJoyride option "maxGap" must be at least "minGap"');
    }

    if (settings.powerUpMax < settings.powerUpMin) {
        throw new RangeError('TeslaJoyride option "powerUpMax" must be at least "powerUpMin"');
    }

    if (settings.maxSpeed < settings.speed) {
        throw new RangeError('TeslaJoyride option "maxSpeed" must be at least "speed"');
    }

    if (settings.thrust <= settings.gravity) {
        throw new RangeError('TeslaJoyride option "thrust" must be stronger than gravity');
    }

    if (!Number.isFinite(settings.hitboxInset) || settings.hitboxInset < 0 || settings.hitboxInset > 6) {
        throw new RangeError('TeslaJoyride option "hitboxInset" must be between 0 and 6 game pixels');
    }

    for (const key of ['storageKey', 'runsKey', 'themeKey']) {
        if (typeof settings[key] !== 'string' || !settings[key].trim()) {
            throw new TypeError(`TeslaJoyride option "${key}" must be a non-empty string`);
        }
    }

    return Object.freeze(settings);
}

function validatePositiveNumber(name, value) {
    if (!Number.isFinite(value) || value <= 0) {
        throw new TypeError(`TeslaJoyride option "${name}" must be a finite positive number`);
    }
}

// ---- physics.js ----
// Rocket sprite stack (game px): nose, N tiled bodies, engine. The hull is 26 px wide.
const ROCKET = Object.freeze({nose: 57, body: 15, engine: 31, hull: 26});

function advanceVertical(position, velocity, acceleration, deltaSeconds, minVelocity = -Infinity, maxVelocity = Infinity) {
    const nextVelocity = Math.min(maxVelocity, Math.max(minVelocity, velocity + acceleration * deltaSeconds));
    return {
        position: position + nextVelocity * deltaSeconds,
        velocity: nextVelocity
    };
}

function advanceHorizontal(position, speed, deltaSeconds) {
    return position - speed * deltaSeconds;
}

function getCarHitbox({x, y, width, height, inset}) {
    const horizontalInset = Math.min(inset, width / 2);
    const verticalInset = Math.min(inset, height / 2);

    return {
        left: x + horizontalInset,
        right: x + width - horizontalInset,
        top: y + verticalInset,
        bottom: y + height - verticalInset
    };
}

function getRocketLength(bodies) {
    return ROCKET.nose + bodies * ROCKET.body + ROCKET.engine;
}

// Separating-axis test: axis-aligned box vs. a rectangle centred at (x, y), rotated by `angle` (0 = nose up).
function boxHitsRotatedRect(box, {x, y, halfWidth, halfLength, angle}) {
    const cos = Math.abs(Math.cos(angle));
    const sin = Math.abs(Math.sin(angle));
    const boxHalfWidth = (box.right - box.left) / 2;
    const boxHalfHeight = (box.bottom - box.top) / 2;
    const dx = x - (box.left + box.right) / 2;
    const dy = y - (box.top + box.bottom) / 2;

    if (Math.abs(dx) > boxHalfWidth + cos * halfWidth + sin * halfLength) return false;
    if (Math.abs(dy) > boxHalfHeight + sin * halfWidth + cos * halfLength) return false;

    const along = Math.abs(-dx * Math.sin(angle) + dy * Math.cos(angle));
    const across = Math.abs(dx * Math.cos(angle) + dy * Math.sin(angle));
    if (across > halfWidth + boxHalfWidth * cos + boxHalfHeight * sin) return false;
    return along <= halfLength + boxHalfWidth * sin + boxHalfHeight * cos;
}

// Charge replaces medals: every quarter of FULL_CHARGE_METRES adds 25%.
function getCharge(metres) {
    return Math.min(4, Math.floor(metres / (FULL_CHARGE_METRES / 4))) * 25;
}

function formatClock(seconds) {
    const total = Math.floor(seconds);
    return [total / 3600, (total % 3600) / 60, total % 60]
        .map((part) => String(Math.floor(part)).padStart(2, '0'))
        .join(':');
}

// ---- storage.js ----
function readBestScore(key, storage = getBrowserStorage()) {
    try {
        const value = Number.parseInt(storage?.getItem(key), 10);
        return Number.isFinite(value) && value >= 0 ? value : 0;
    } catch {
        return 0;
    }
}

function writeBestScore(key, value, storage = getBrowserStorage()) {
    try {
        storage?.setItem(key, String(value));
        return Boolean(storage);
    } catch {
        return false;
    }
}

function readText(key, storage = getBrowserStorage()) {
    try {
        return storage?.getItem(key) ?? null;
    } catch {
        return null;
    }
}

function writeText(key, value, storage = getBrowserStorage()) {
    try {
        storage?.setItem(key, value);
        return Boolean(storage);
    } catch {
        return false;
    }
}

function isNewBestScore(score, bestScore, debug = false) {
    return !debug && score > bestScore;
}

function getBrowserStorage() {
    try {
        return globalThis.localStorage;
    } catch {
        return null;
    }
}

// ---- joyride.js ----
/*
 * Tesla Joyride
 * Jetpack-style runner: hold to fire the Roadster's thrusters, release to fall.
 * Canvas edition: 640×360 game px rendered at 3× (1920×1080) and fitted to the window.
 */




function TeslaJoyride(elementId, options = {}) {
    const settings = createSettings(options);
    const container = document.getElementById(elementId);

    if (!container) {
        throw new Error(`Element with id "${elementId}" not found`);
    }

    const State = Object.freeze({
        READY: 'ready',
        PLAYING: 'playing',
        GAME_OVER: 'game-over',
        DESTROYED: 'destroyed'
    });

    // Designed frame (1920×1080). The live stage grows past it to match the window's shape.
    const BASE_WIDTH = GAME_WIDTH * RENDER_SCALE;
    const BASE_HEIGHT = GAME_HEIGHT * RENDER_SCALE;
    const IMAGE_PATH = '../flappy-assets/image/'; // shared with Tesla Bird
    const FONT = '"Jersey 10", monospace';
    const CAR = {x: 110, width: 42, height: 12, spriteHeight: 15};
    const WHEELS = [{x: 9, frameOffset: 0}, {x: 33, frameOffset: 2}];
    const SMOKE = {frames: 14, splashFrames: 4, width: 12, height: 34, seconds: 0.5, every: 0.045};
    const GROUND_DEPTH = 8; // track strip under the wheels
    const FIN_OVERHANG = 7; // nose and engine sprites stick out past the 26 px hull on each side
    const MISSILE = {warnSeconds: 1.2, lockSeconds: 0.45, extraSpeed: 300, salvoOffset: 70};
    const GATE_HALF = 40; // half the opening between the two rockets of a gate
    // Colours match the pickup sprites; they tint the HUD labels and the slow-mo screen.
    const POWER_UPS = {
        shield: {label: 'SHIELD', sprite: 'powerup_shield', color: '#4fd8ff', seconds: 0}, // lasts until the next hit
        boost: {label: 'BOOST', sprite: 'powerup_boost', color: '#ffb627', seconds: 3},
        slowmo: {label: 'SLOW-MO', sprite: 'powerup_slowmo', color: '#5b8cff', seconds: 6}
    };
    const POWER_UP_KINDS = Object.keys(POWER_UPS);
    const BOOST_FACTOR = 2.2;
    const SLOWMO_FACTOR = 0.55;
    const GRACE_SECONDS = 1.2; // blinking pass-through after a boost ends or a shield breaks
    const EXTRA_LIVES = 1; // spare lives per run
    const REVIVE_GRACE_SECONDS = 2;
    const PICKUP_SIZE = 24;
    const EXPLOSION = {frames: 8, size: 32, seconds: 0.6};
    const WARNING_SIZE = 24; // warning_missile.png: tracking frame, then locked frame
    const ROCKET_ANGLES = [0, 1, 2, 3, 4, 5, 6, 7].map((step) => step * Math.PI / 4);
    const PARALLAX = 0.2;
    const INPUT_DELAY_MS = 400;
    const GAME_KEYS = ['ArrowUp', 'KeyW', 'Space'];
    const UI_SELECTOR = '#debug, .tb-theme-toggle';
    const TOGGLE_THEMES = [{name: 'night', label: 'NIGHT'}, {name: 'dawn', label: 'DAWN'}, {name: 'day', label: 'DAY'}];
    const PLAY_BUTTON = {x: 840, y: 864, width: 240, height: 96};
    const TIMELINE_LINE_Y = 48; // progress line, below the timeline's top
    const TIMELINE_NODES = [
        {metres: 0, label: 'LIFTOFF'},
        {metres: FULL_CHARGE_METRES / 4, label: '25%'},
        {metres: FULL_CHARGE_METRES / 2, label: '50%'},
        {metres: FULL_CHARGE_METRES * 3 / 4, label: '75%'},
        {metres: FULL_CHARGE_METRES, label: 'FULL'}
    ];
    const COLOR = {
        text: '#f4f4f4',
        label: '#d8dade',
        secondary: '#9a9da4',
        red: '#e0262f',
        redLight: '#ff5a5f',
        panel: '#101114',
        inactive: '#4a4d55',
        track: '#7a7d85',
        title: '#eaf3ff',
        key: '#0b0a1a'
    };

    const images = {};
    const gaugeCache = new Map();
    const gaugeGeometry = createGaugeGeometry();

    let state = State.READY;
    let isLoaded = false;
    let isThrusting = false;
    let obstacles = [];
    let warnings = [];
    let smokes = [];
    let pickups = [];
    let explosions = [];
    let hasShield = false;
    let extraLives = 0;
    let boostTime = 0;
    let slowTime = 0;
    let graceTime = 0;
    let powerUpTimer = 0;
    let isPickupDue = false;
    let pickupAt = 0; // spawn countdown at which a pickup lands midway between two rockets
    let distance = 0;
    let speed = settings.speed;
    let score = 0; // metres
    let bestScore = readBestScore(settings.storageKey);
    let runs = readBestScore(settings.runsKey); // same non-negative integer format as the best score
    let isNewBest = false;
    let screenWidth = BASE_WIDTH;
    let screenHeight = BASE_HEIGHT;
    let gameWidth = GAME_WIDTH;
    let gameHeight = GAME_HEIGHT;
    let carX = 0;
    let carY = 0;
    let velocityY = 0;
    let carAngle = 0;
    let spawnCountdown = 0;
    let missileTimer = 0;
    let smokeTimer = 0;
    let scrolled = 0;
    let elapsed = 0;
    let clock = 0;
    let hasLanded = false;
    let gameOverShownAt = 0;
    let frameId = 0;
    let lastFrameTime = 0;

    container.classList.add('flappy-game');
    container.setAttribute('role', 'region');
    container.setAttribute('aria-label', 'Tesla Joyride');

    const stage = document.createElement('div');
    stage.className = 'tb-stage';

    // Three tiles (normal, mirrored, normal) loop seamlessly while the backdrop scrolls.
    const backdrop = document.createElement('div');
    backdrop.className = 'tb-backdrop';
    const backgrounds = [0, 1, 2].map((index) => {
        const image = document.createElement('img');
        image.className = index === 1 ? 'tb-background tb-mirrored' : 'tb-background';
        image.alt = '';
        return image;
    });
    backdrop.append(...backgrounds);

    const dim = document.createElement('div');
    dim.className = 'tb-dim';

    const canvas = document.createElement('canvas');
    canvas.className = 'tb-canvas';
    canvas.setAttribute('aria-hidden', 'true');
    const ctx = canvas.getContext('2d');

    const status = document.createElement('output');
    status.className = 'tb-visually-hidden';
    status.setAttribute('aria-live', 'polite');
    status.textContent = 'Hold Space or the mouse button to fly. Press to start.';

    const themeToggle = document.createElement('div');
    themeToggle.className = 'tb-theme-toggle';
    themeToggle.setAttribute('role', 'group');
    themeToggle.setAttribute('aria-label', 'Theme');
    themeToggle.hidden = true;
    for (const {name, label} of TOGGLE_THEMES) {
        const button = document.createElement('button');
        button.type = 'button';
        button.dataset.theme = name;
        button.textContent = label;
        themeToggle.append(button);
    }
    themeToggle.addEventListener('click', handleThemeClick);

    // An explicit theme option (e.g. ?theme=) wins, then the last splash-screen choice, then the browser's light/dark setting.
    const savedTheme = readText(settings.themeKey);
    const browserTheme = window.matchMedia?.('(prefers-color-scheme: light)').matches ? 'day' : settings.theme;
    let themeName = options.theme ?? (Object.hasOwn(THEMES, savedTheme ?? '') ? savedTheme : browserTheme);
    applyTheme(themeName);

    stage.append(backdrop, dim, canvas, themeToggle);
    container.replaceChildren(stage, status);

    container.addEventListener('pointerdown', handlePointerDown);
    container.addEventListener('contextmenu', preventContextMenu);
    window.addEventListener('pointerup', releaseThrust);
    window.addEventListener('pointercancel', releaseThrust);
    window.addEventListener('blur', releaseThrust);
    document.addEventListener('keydown', handleKeyDown);
    document.addEventListener('keyup', handleKeyUp);

    const resizeObserver = typeof ResizeObserver === 'function' ? new ResizeObserver(fitStage) : null;
    if (resizeObserver) {
        resizeObserver.observe(container);
    } else {
        window.addEventListener('resize', fitStage);
    }
    fitStage();

    loadAssets().then(() => {
        if (state === State.DESTROYED) return;
        isLoaded = true;
        showStartScreen();
        lastFrameTime = performance.now();
        frameId = requestAnimationFrame(gameLoop);
    });

    if (settings.debug) {
        console.info('Tesla Joyride debug mode enabled', settings);
    }

    return Object.freeze({
        start: startGame,
        restart: showStartScreen,
        destroy,
        getState: () => state,
        getScore: () => score,
        getBestScore: () => bestScore,
        getDifficulty: () => settings.difficulty,
        getTheme: () => themeName
    });

    function loadAssets() {
        const names = [
            'car_idle', 'car_crashed', 'smoke_v3_strip', 'rocket_nose', 'rocket_body',
            'rocket_engine', 'btn_play', 'hint_arrow', 'powerup_shield', 'powerup_boost', 'powerup_slowmo',
            'shield_bubble', 'explosion_strip', 'warning_missile'
        ];
        const imageLoads = names.map((name) => new Promise((resolve, reject) => {
            const image = new Image();
            image.onload = resolve;
            image.onerror = () => reject(new Error(`Tesla Joyride could not load ${name}.png`));
            image.src = `${IMAGE_PATH}${name}.png`;
            images[name] = image;
        }));
        // A missing web font only changes the typeface, so it must not block the game.
        const fontLoad = document.fonts?.load(`56px ${FONT}`).catch(() => null);
        return Promise.all([...imageLoads, fontLoad]);
    }

    // The shorter side keeps the designed size; the other grows (in whole game px) to fill the window.
    function fitStage() {
        const windowWidth = container.clientWidth || BASE_WIDTH;
        const windowHeight = container.clientHeight || BASE_HEIGHT;
        const isWider = windowWidth / windowHeight > BASE_WIDTH / BASE_HEIGHT;
        const snap = (value) => Math.round(value / RENDER_SCALE) * RENDER_SCALE;

        screenWidth = isWider ? snap(BASE_HEIGHT * windowWidth / windowHeight) : BASE_WIDTH;
        screenHeight = isWider ? BASE_HEIGHT : snap(BASE_WIDTH * windowHeight / windowWidth);
        gameWidth = screenWidth / RENDER_SCALE;
        gameHeight = screenHeight / RENDER_SCALE;

        stage.style.width = `${screenWidth}px`;
        stage.style.height = `${screenHeight}px`;
        if (canvas.width !== screenWidth) canvas.width = screenWidth;
        if (canvas.height !== screenHeight) canvas.height = screenHeight;
        // max, not min: snapping can leave the stage a fraction short, and a hairline bar is worse than a 1 px crop.
        const scale = Math.max(windowWidth / screenWidth, windowHeight / screenHeight);
        stage.style.transform = `translate(-50%, -50%) scale(${scale})`;

        if (state !== State.READY) carY = Math.min(carY, getGroundY());
    }

    function getStartX() {
        return (gameWidth - CAR.width) / 2;
    }

    function getStartY() {
        return gameHeight / 2 - 10;
    }

    // Car top when its wheels touch the track.
    function getGroundY() {
        return gameHeight - GROUND_DEPTH - CAR.spriteHeight;
    }

    // Offset that centres the designed 1920×1080 menu layout on the live stage.
    function getMenuOffset() {
        return {x: (screenWidth - BASE_WIDTH) / 2, y: (screenHeight - BASE_HEIGHT) / 2};
    }

    function random(minimum, maximum) {
        return minimum + Math.random() * (maximum - minimum);
    }

    // ---- State ----

    function showStartScreen() {
        if (state === State.DESTROYED) return;

        state = State.READY;
        container.dataset.gameState = state;
        score = 0;
        distance = 0;
        speed = settings.speed;
        elapsed = 0;
        velocityY = 0;
        carAngle = 0;
        carX = getStartX();
        carY = getStartY();
        obstacles = [];
        warnings = [];
        smokes = [];
        pickups = [];
        explosions = [];
        hasShield = false;
        extraLives = EXTRA_LIVES;
        boostTime = 0;
        slowTime = 0;
        graceTime = 0;
        powerUpTimer = random(3, 6); // the first pickup comes early so players learn what it does
        isPickupDue = false;
        spawnCountdown = gameWidth * 0.4;
        pickupAt = spawnCountdown / 2;
        missileTimer = random(1.5, 3);
        isNewBest = false;
        hasLanded = false;
        status.textContent = 'Hold Space or the mouse button to fly. Press to start.';
        themeToggle.hidden = false;
    }

    function applyTheme(name) {
        const theme = THEMES[name];
        themeName = name;
        for (const image of backgrounds) image.src = IMAGE_PATH + theme.background;
        dim.style.background = theme.dimColor;
        dim.style.opacity = String(theme.dim);
        for (const button of themeToggle.children) {
            button.setAttribute('aria-pressed', String(button.dataset.theme === name));
        }
    }

    function handleThemeClick(event) {
        const button = event.target.closest('button');
        if (!button) return;
        applyTheme(button.dataset.theme);
        writeText(settings.themeKey, themeName);
        // Mouse clicks drop focus so the next Space starts the game instead of re-pressing the button.
        if (event.detail > 0) button.blur();
    }

    function startGame() {
        if (state !== State.READY || !isLoaded) return;

        themeToggle.hidden = true;
        state = State.PLAYING;
        container.dataset.gameState = state;
        runs += 1;
        writeBestScore(settings.runsKey, runs);
        status.textContent = '';
    }

    function crash() {
        state = State.GAME_OVER;
        container.dataset.gameState = state;
        velocityY = Math.max(0, velocityY);
        warnings = [];
        boostTime = 0;
        slowTime = 0;
        graceTime = 0;
        hasLanded = false;

        isNewBest = isNewBestScore(score, bestScore, settings.debug);
        if (isNewBest) {
            bestScore = score;
            writeBestScore(settings.storageKey, bestScore);
        }
    }

    function land() {
        carY = getGroundY();
        velocityY = 0;
        hasLanded = true;
        gameOverShownAt = performance.now();
        status.textContent = `Game over. Distance ${score} metres, best ${bestScore}. Press Space to play again.`;
    }

    function canRestart() {
        return state === State.GAME_OVER && hasLanded && performance.now() - gameOverShownAt >= INPUT_DELAY_MS;
    }

    // ---- Rockets ----

    function addRocket(x, y, angle, bodies, spin = 0, extraSpeed = 0) {
        obstacles.push({x, y, angle, spin, bodies, length: getRocketLength(bodies), extraSpeed, collided: false, smashed: false});
    }

    // Returns half the obstacle's width (fins included), so the next gap can be measured edge to edge.
    function spawnObstacle() {
        return score >= settings.gatesFrom && Math.random() < 0.3 ? spawnGate() : spawnRocket();
    }

    // Floating rockets: any of 8 orientations, longer and more often spinning as the run goes on.
    function spawnRocket() {
        const bodies = Math.floor(Math.random() * (2 + Math.min(4, Math.floor(score / 120))));
        const length = getRocketLength(bodies);
        const angle = ROCKET_ANGLES[Math.floor(Math.random() * ROCKET_ANGLES.length)];
        const spin = score > 150 && Math.random() < 0.3 ? (Math.random() < 0.5 ? -1.6 : 1.6) : 0;
        const cos = Math.abs(Math.cos(angle));
        const sin = Math.abs(Math.sin(angle));
        const extentY = spin ? length / 2 : cos * length / 2 + sin * ROCKET.hull / 2;
        const extentX = spin ? length / 2 : sin * length / 2 + cos * ROCKET.hull / 2;
        const groundLine = gameHeight - GROUND_DEPTH;
        addRocket(gameWidth + extentX + FIN_OVERHANG, random(extentY, groundLine - extentY), angle, bodies, spin);
        return extentX + FIN_OVERHANG;
    }

    // Gate: one rocket hangs nose-down from the ceiling, one stands on the track; fly through the opening.
    function spawnGate() {
        const groundLine = gameHeight - GROUND_DEPTH;
        const center = random(GATE_HALF + 30, groundLine - GATE_HALF - 30);
        const x = gameWidth + ROCKET.hull / 2 + FIN_OVERHANG;
        const bodiesFor = (span) => Math.max(0, Math.ceil((span - getRocketLength(0)) / ROCKET.body));
        const upper = bodiesFor(center - GATE_HALF);
        const lower = bodiesFor(groundLine - center - GATE_HALF);
        addRocket(x, center - GATE_HALF - getRocketLength(upper) / 2, Math.PI, upper);
        addRocket(x, center + GATE_HALF + getRocketLength(lower) / 2, 0, lower);
        return ROCKET.hull / 2 + FIN_OVERHANG;
    }

    function launchMissile(y) {
        addRocket(gameWidth + getRocketLength(0) / 2 + FIN_OVERHANG, y, -Math.PI / 2, 0, 0, MISSILE.extraSpeed); // nose left
    }

    function smash(rocket) {
        rocket.smashed = true;
        explosions.push({x: carX + CAR.width, y: carY + CAR.height / 2, age: 0});
    }

    function activatePowerUp(kind) {
        if (kind === 'shield') hasShield = true;
        if (kind === 'boost') {
            boostTime = POWER_UPS.boost.seconds;
            slowTime = 0;
            warnings = [];
        }
        if (kind === 'slowmo') slowTime = POWER_UPS.slowmo.seconds;
        status.textContent = `${POWER_UPS[kind].label} on`;
    }

    // Boost and slow-mo change how fast the whole world moves past the car.
    function getSpeedFactor() {
        if (boostTime > 0) return BOOST_FACTOR;
        return slowTime > 0 ? SLOWMO_FACTOR : 1;
    }

    function getRocketHitbox(rocket) {
        return {
            x: rocket.x,
            y: rocket.y,
            halfWidth: ROCKET.hull / 2 - settings.hitboxInset,
            halfLength: rocket.length / 2 - 6, // the nose tip tapers, so it is forgiven
            angle: rocket.angle
        };
    }

    // ---- Loop ----

    function gameLoop(timestamp) {
        if (state === State.DESTROYED) return;

        const deltaSeconds = Math.min((timestamp - lastFrameTime) / 1000, 0.032);
        lastFrameTime = timestamp;
        clock += deltaSeconds;
        update(deltaSeconds);
        render();
        frameId = requestAnimationFrame(gameLoop);
    }

    function update(deltaSeconds) {
        // Ease the pitch toward its target so the car tilts like a vehicle.
        carAngle += (getTargetAngle() - carAngle) * Math.min(1, deltaSeconds * 8);

        if (state === State.READY) {
            carX = getStartX();
            carY = getStartY() + Math.sin(clock * 3) * 2; // ±6 screen px bob
            return;
        }

        if (state === State.GAME_OVER) {
            speed *= Math.exp(-1.6 * deltaSeconds); // the wreck skids to a stop
            moveWorld(deltaSeconds);
            if (hasLanded) return;
            const motion = advanceVertical(carY, velocityY, settings.gravity, deltaSeconds, -Infinity, settings.maxFall);
            carY = motion.position;
            velocityY = motion.velocity;
            if (carY >= getGroundY()) {
                carY = getGroundY();
                velocityY = velocityY > 120 ? -velocityY * 0.35 : 0; // one or two bounces, then slide
                if (velocityY === 0 && speed < 25) land();
            }
            return;
        }

        elapsed += deltaSeconds;
        speed = Math.min(settings.maxSpeed, speed + settings.acceleration * deltaSeconds);
        const worldSpeed = speed * getSpeedFactor();
        distance += worldSpeed * deltaSeconds;
        score = Math.floor(distance / PX_PER_METRE);
        carX += (CAR.x - carX) * Math.min(1, deltaSeconds * 6);

        if (boostTime > 0) {
            boostTime -= deltaSeconds;
            if (boostTime <= 0) graceTime = GRACE_SECONDS;
            // Autopilot: the boost holds the car mid-air whatever the input.
            carY += (gameHeight * 0.45 - carY) * Math.min(1, deltaSeconds * 4);
            velocityY = 0;
        } else {
            const acceleration = settings.gravity - (isThrusting ? settings.thrust : 0);
            const motion = advanceVertical(carY, velocityY, acceleration, deltaSeconds, -settings.maxRise, settings.maxFall);
            carY = motion.position;
            velocityY = motion.velocity;
        }
        slowTime = Math.max(0, slowTime - deltaSeconds);
        graceTime = Math.max(0, graceTime - deltaSeconds);

        // Ceiling and track are safe: the car scrapes along them like Barry in Jetpack Joyride.
        if (carY < 0) {
            carY = 0;
            velocityY = Math.max(0, velocityY);
        } else if (carY > getGroundY()) {
            carY = getGroundY();
            velocityY = Math.min(0, velocityY);
        }

        if (isThrusting || boostTime > 0) {
            smokeTimer -= deltaSeconds;
            while (smokeTimer <= 0) {
                smokeTimer += SMOKE.every;
                for (const wheel of WHEELS) smokes.push({x: carX + wheel.x, y: carY + 10, age: wheel.frameOffset * 0.02});
            }
        }

        moveWorld(deltaSeconds);

        const countdownBefore = spawnCountdown;
        spawnCountdown -= worldSpeed * deltaSeconds;
        if (isPickupDue && countdownBefore > pickupAt && spawnCountdown <= pickupAt) spawnPickup();
        if (spawnCountdown <= 0) {
            const halfWidth = spawnObstacle();
            // sqrt: gaps grow slower than speed, so rockets arrive more often later in the run.
            const gap = random(settings.minGap, settings.maxGap) * Math.sqrt(speed / settings.speed);
            // Edge to edge: a long or spinning rocket must not leave too little room before the next one.
            spawnCountdown = gap + halfWidth * 2;
            pickupAt = gap / 2 + PICKUP_SIZE / 2;
        }
        updateMissiles(deltaSeconds);

        const hitbox = getCarHitbox({x: carX, y: carY, width: CAR.width, height: CAR.height, inset: settings.hitboxInset});
        updatePickups(deltaSeconds, hitbox);

        for (const rocket of obstacles) {
            if (!boxHitsRotatedRect(hitbox, getRocketHitbox(rocket))) continue;
            if (boostTime > 0) {
                smash(rocket);
            } else if (graceTime > 0) {
                continue;
            } else if (hasShield) {
                hasShield = false;
                graceTime = GRACE_SECONDS;
                smash(rocket);
            } else if (extraLives > 0) {
                // Spare life: the hit is forgiven with a longer blink, and pending missiles are called off.
                extraLives -= 1;
                graceTime = REVIVE_GRACE_SECONDS;
                warnings = [];
                smash(rocket);
                status.textContent = 'Extra life used';
            } else if (settings.debug) {
                rocket.collided = true;
            } else {
                crash();
                return;
            }
        }
        obstacles = obstacles.filter((rocket) => !rocket.smashed);
    }

    function moveWorld(deltaSeconds) {
        const factor = getSpeedFactor();
        const worldSpeed = speed * factor;
        for (const rocket of obstacles) {
            rocket.x = advanceHorizontal(rocket.x, (speed + rocket.extraSpeed) * factor, deltaSeconds);
            rocket.angle += rocket.spin * factor * deltaSeconds;
        }
        obstacles = obstacles.filter((rocket) => rocket.x + rocket.length / 2 + FIN_OVERHANG > 0);

        for (const item of [...smokes, ...pickups, ...explosions]) {
            item.age += deltaSeconds;
            item.x = advanceHorizontal(item.x, worldSpeed, deltaSeconds);
        }
        smokes = smokes.filter((smoke) => smoke.age < SMOKE.seconds);
        pickups = pickups.filter((pickup) => pickup.x > -PICKUP_SIZE);
        explosions = explosions.filter((explosion) => explosion.age < EXPLOSION.seconds);
        scrolled += worldSpeed * deltaSeconds;
    }

    // Missile warnings track the car, lock for a moment, then launch along the locked line.
    // Later in the run a second warning tracks a line above or below the car (a salvo).
    function updateMissiles(deltaSeconds) {
        if (score >= settings.missileFrom && boostTime <= 0) missileTimer -= deltaSeconds;
        if (missileTimer <= 0) {
            missileTimer = random(1.6, 4);
            const y = carY + CAR.height / 2;
            warnings.push({age: 0, y, offset: 0});
            if (score >= settings.salvosFrom && Math.random() < 0.4) {
                warnings.push({age: 0, y, offset: Math.random() < 0.5 ? -MISSILE.salvoOffset : MISSILE.salvoOffset});
            }
        }

        const groundLine = gameHeight - GROUND_DEPTH;
        for (const warning of warnings) {
            warning.age += deltaSeconds;
            if (warning.age < MISSILE.warnSeconds - MISSILE.lockSeconds) {
                const target = Math.min(groundLine - 10, Math.max(10, carY + CAR.height / 2 + warning.offset));
                warning.y += (target - warning.y) * Math.min(1, deltaSeconds * 4);
            }
            if (warning.age >= MISSILE.warnSeconds) launchMissile(warning.y);
        }
        warnings = warnings.filter((warning) => warning.age < MISSILE.warnSeconds);
    }

    // A due pickup waits for the middle of the next gap between rockets, so it never spawns inside one.
    function spawnPickup() {
        isPickupDue = false;
        const kind = POWER_UP_KINDS[Math.floor(Math.random() * POWER_UP_KINDS.length)];
        pickups.push({kind, x: gameWidth + PICKUP_SIZE / 2, baseY: random(30, gameHeight - GROUND_DEPTH - 30), y: 0, age: 0});
    }

    // Pickups bob on a sine wave and drift with the world; touching one switches its power-up on.
    function updatePickups(deltaSeconds, hitbox) {
        if (!isPickupDue) powerUpTimer -= deltaSeconds;
        if (powerUpTimer <= 0) {
            powerUpTimer = random(settings.powerUpMin, settings.powerUpMax);
            isPickupDue = true;
        }

        const half = PICKUP_SIZE / 2;
        for (const pickup of pickups) {
            pickup.y = pickup.baseY + Math.sin(pickup.age * 3) * 8;
            if (!boxHitsRotatedRect(hitbox, {x: pickup.x, y: pickup.y, halfWidth: half, halfLength: half, angle: 0})) continue;
            pickup.taken = true;
            activatePowerUp(pickup.kind);
        }
        pickups = pickups.filter((pickup) => !pickup.taken);
    }

    // ---- Rendering ----

    function render() {
        // Parallax: the backdrop scrolls slower than the track; three tiles wrap every two screen widths.
        backdrop.style.transform = `translateX(${-((scrolled * RENDER_SCALE * PARALLAX) % (screenWidth * 2))}px)`;

        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, screenWidth, screenHeight);
        ctx.imageSmoothingEnabled = false;

        const isHudShown = state === State.PLAYING || (state === State.GAME_OVER && !hasLanded);
        if (isHudShown) drawHudShade(); // behind the sprites, so the car on the track is not darkened
        drawTrack();
        if (boostTime > 0) drawSpeedLines();
        if (state !== State.READY) {
            obstacles.forEach(drawRocket);
            pickups.forEach(drawPickup);
            drawWarnings();
        }
        drawSmokes();
        drawCar();
        drawExplosions();
        if (slowTime > 0) {
            ctx.setTransform(1, 0, 0, 1, 0, 0);
            ctx.globalAlpha = 0.1;
            fillRect(0, 0, screenWidth, screenHeight, POWER_UPS.slowmo.color);
            ctx.globalAlpha = 1;
        }

        const menu = getMenuOffset();
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        if (state === State.READY) {
            ctx.translate(menu.x, menu.y);
            drawStartScreen();
        } else if (state === State.GAME_OVER && hasLanded) {
            drawGameOverScreen();
        } else {
            drawHud();
        }
    }

    function drawTrack() {
        ctx.setTransform(RENDER_SCALE, 0, 0, RENDER_SCALE, 0, 0);
        const top = gameHeight - GROUND_DEPTH;
        ctx.globalAlpha = 0.85;
        fillRect(0, top, gameWidth, GROUND_DEPTH, COLOR.key);
        ctx.globalAlpha = 0.6;
        fillRect(0, top, gameWidth, 1, COLOR.title);
        ctx.globalAlpha = 0.35;
        for (let x = -(scrolled % 24); x < gameWidth; x += 24) fillRect(Math.round(x), top + 4, 12, 1, COLOR.title);
        ctx.globalAlpha = 1;
    }

    // Rocket stack in local space (nose up, centred on 0,0), then rotated into place.
    function drawRocket(rocket) {
        const {rocket_nose: nose, rocket_body: body, rocket_engine: engine} = images;
        const top = -rocket.length / 2;
        const hullLeft = -ROCKET.hull / 2;
        ctx.setTransform(RENDER_SCALE, 0, 0, RENDER_SCALE, 0, 0);
        ctx.translate(Math.round(rocket.x * RENDER_SCALE) / RENDER_SCALE, Math.round(rocket.y * RENDER_SCALE) / RENDER_SCALE);
        ctx.rotate(rocket.angle);

        const frame = Math.floor(clock / SMOKE.seconds * SMOKE.frames);
        drawSmokeFrame(-6, -top - 6, frame % SMOKE.splashFrames);
        drawSmokeFrame(6, -top - 6, (frame + 2) % SMOKE.splashFrames);

        for (let index = 0; index < rocket.bodies; index += 1) {
            ctx.drawImage(body, hullLeft, top + ROCKET.nose + index * ROCKET.body);
        }
        ctx.drawImage(engine, hullLeft - FIN_OVERHANG, top + ROCKET.nose + rocket.bodies * ROCKET.body);
        ctx.drawImage(nose, hullLeft - FIN_OVERHANG + 2 / RENDER_SCALE, top); // +2 screen px centres the nose on the body

        if (settings.debug) {
            const {halfWidth, halfLength} = getRocketHitbox(rocket);
            ctx.strokeStyle = rocket.collided ? COLOR.red : '#4fd8ff';
            ctx.lineWidth = 1 / RENDER_SCALE;
            ctx.strokeRect(-halfWidth, -halfLength, halfWidth * 2, halfLength * 2);
        }
    }

    function drawWarnings() {
        const blink = Math.floor(clock * 8) % 2 === 0;
        for (const warning of warnings) {
            const isLocked = warning.age >= MISSILE.warnSeconds - MISSILE.lockSeconds;
            if (isLocked && !blink) continue;
            ctx.setTransform(RENDER_SCALE, 0, 0, RENDER_SCALE, 0, 0);
            const half = WARNING_SIZE / 2;
            ctx.drawImage(
                images.warning_missile,
                isLocked ? WARNING_SIZE : 0, 0, WARNING_SIZE, WARNING_SIZE,
                gameWidth - 4 - WARNING_SIZE, Math.round(warning.y) - half, WARNING_SIZE, WARNING_SIZE
            );
        }
    }

    function drawPickup(pickup) {
        const image = images[POWER_UPS[pickup.kind].sprite];
        ctx.setTransform(RENDER_SCALE, 0, 0, RENDER_SCALE, 0, 0);
        ctx.drawImage(image, Math.round(pickup.x - image.width / 2), Math.round(pickup.y - image.height / 2));
    }

    function drawExplosions() {
        ctx.setTransform(RENDER_SCALE, 0, 0, RENDER_SCALE, 0, 0);
        const half = EXPLOSION.size / 2;
        for (const explosion of explosions) {
            const frame = Math.min(EXPLOSION.frames - 1, Math.floor(explosion.age / EXPLOSION.seconds * EXPLOSION.frames));
            ctx.drawImage(
                images.explosion_strip,
                frame * EXPLOSION.size, 0, EXPLOSION.size, EXPLOSION.size,
                Math.round(explosion.x) - half, Math.round(explosion.y) - half, EXPLOSION.size, EXPLOSION.size
            );
        }
    }

    function drawSpeedLines() {
        ctx.setTransform(RENDER_SCALE, 0, 0, RENDER_SCALE, 0, 0);
        ctx.globalAlpha = 0.45;
        for (let index = 0; index < 14; index += 1) {
            const y = (index * 53 + 17) % (gameHeight - GROUND_DEPTH);
            const x = gameWidth - ((clock * 900 + index * 137) % (gameWidth + 60));
            fillRect(Math.round(x), y, 40, 1, COLOR.title);
        }
        ctx.globalAlpha = 1;
    }

    function drawSmokes() {
        ctx.setTransform(RENDER_SCALE, 0, 0, RENDER_SCALE, 0, 0);
        for (const smoke of smokes) {
            drawSmokeFrame(smoke.x, smoke.y, Math.floor(smoke.age / SMOKE.seconds * SMOKE.frames));
        }
    }

    function drawCar() {
        const centerX = CAR.width / 2;
        const centerY = CAR.spriteHeight / 2;
        ctx.setTransform(RENDER_SCALE, 0, 0, RENDER_SCALE, 0, 0);
        ctx.translate(carX + centerX, carY + centerY);
        ctx.rotate(carAngle * Math.PI / 180);
        ctx.translate(-centerX, -centerY);

        if (state === State.READY) {
            // Splash screen: loop only the first frames so the smoke idles instead of puffing out.
            const frame = Math.floor(clock / SMOKE.seconds * SMOKE.frames);
            for (const wheel of WHEELS) {
                drawSmokeFrame(wheel.x, 10, (frame + wheel.frameOffset) % SMOKE.splashFrames);
            }
        }

        if (graceTime > 0 && Math.floor(clock * 10) % 2) ctx.globalAlpha = 0.35;
        ctx.drawImage(state === State.GAME_OVER ? images.car_crashed : images.car_idle, 0, 0);
        ctx.globalAlpha = 1;

        // Shield dome over the car. Screen blending drops its dark inside, so the car stays visible.
        if (hasShield && state === State.PLAYING) {
            const bubble = images.shield_bubble;
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.8 + Math.sin(clock * 6) * 0.2;
            ctx.drawImage(bubble, Math.round((CAR.width - bubble.width) / 2), CAR.spriteHeight + 3 - bubble.height);
            ctx.globalAlpha = 1;
            ctx.globalCompositeOperation = 'source-over';
        }

        if (settings.debug) {
            const inset = settings.hitboxInset;
            ctx.setTransform(RENDER_SCALE, 0, 0, RENDER_SCALE, 0, 0);
            ctx.strokeStyle = '#4fd8ff';
            ctx.lineWidth = 1 / RENDER_SCALE;
            ctx.strokeRect(carX + inset, carY + inset, CAR.width - inset * 2, CAR.height - inset * 2);
        }
    }

    // Draws one plume frame with its top centred on (x, y) in the current transform.
    function drawSmokeFrame(x, y, frame) {
        if (frame >= SMOKE.frames) return;
        ctx.drawImage(
            images.smoke_v3_strip,
            frame * SMOKE.width, 0, SMOKE.width, SMOKE.height,
            x - SMOKE.width / 2, y, SMOKE.width, SMOKE.height
        );
    }

    function getTargetAngle() {
        if (state === State.READY) return 0;
        if (state === State.GAME_OVER) return hasLanded ? 4 : 18;
        if (carY >= getGroundY() && !isThrusting) return 0;
        if (velocityY < 0) return -10;
        return -10 + 25 * Math.min(1, velocityY / 400); // nose-down tops out at 15°
    }

    function drawStartScreen() {
        drawText('TESLA JOYRIDE', BASE_WIDTH / 2, 180, 220, COLOR.title, {align: 'center', spacing: 12, shadow: 8});

        // "ROCKET" badge overlapping the lower right of the title, slightly tilted.
        setFont(220, 12);
        const titleRight = BASE_WIDTH / 2 + (ctx.measureText('TESLA JOYRIDE').width - 12) / 2;
        ctx.save();
        ctx.translate(titleRight, 316);
        ctx.rotate(-4 * Math.PI / 180);
        drawText('ROCKET', 0, 0, 72, COLOR.red, {align: 'right', spacing: 6, shadow: 4});
        ctx.restore();
        ctx.drawImage(images.hint_arrow, 946, 600, 27, 24);

        // HOLD [CLICK] OR [SPACE], centred at top 656 with a 28 px gap.
        const size = 56;
        const {ascent, descent} = getFontMetrics(size);
        setFont(size, 3);
        const keyHeight = ascent + descent + 8;
        const parts = [
            {text: 'HOLD', key: false},
            {text: 'CLICK', key: true},
            {text: 'OR', key: false},
            {text: 'SPACE', key: true}
        ].map((part) => ({...part, width: ctx.measureText(part.text).width + (part.key ? 56 : 0)}));
        const totalWidth = parts.reduce((sum, part) => sum + part.width, 0) + 28 * (parts.length - 1);
        let x = BASE_WIDTH / 2 - totalWidth / 2;
        const baseline = 656 + 4 + ascent;

        for (const part of parts) {
            if (part.key) {
                fillRect(x, 656, part.width, keyHeight, COLOR.title);
                fillRect(x + 4, 660, part.width - 8, keyHeight - 8, COLOR.key);
                fillText(part.text, x + 28, baseline, COLOR.title);
            } else {
                fillText(part.text, x + 4, baseline + 4, '#000');
                fillText(part.text, x, baseline, COLOR.title);
            }
            x += part.width + 28;
        }
    }

    // Dark bands under the HUD text: bottom for the telemetry, top-right corner for power-ups.
    function drawHudShade() {
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        [0.15, 0.35, 0.55, 0.7, 0.8].forEach((alpha, index) => {
            ctx.globalAlpha = alpha;
            fillRect(0, screenHeight - 300 + index * 60, screenWidth, 60, '#000');
        });
        [0.5, 0.3, 0.12].forEach((alpha, index) => {
            ctx.globalAlpha = alpha;
            fillRect(0, index * 60, screenWidth, 60, '#000');
        });
        ctx.globalAlpha = 1;
    }

    function drawHud() {
        // Designed at 1920×1080 and pinned to the bottom. The clock's digits are centred on the
        // progress line, which also keeps them clear of the car driving on the track.
        const extraY = screenHeight - BASE_HEIGHT;
        const extraX = screenWidth - BASE_WIDTH;
        const timelineTop = 913 + extraY;
        drawClock(72, 'left', {centerY: timelineTop + TIMELINE_LINE_Y + 1.5});

        // Top-right corner: run label, then spare lives (a car icon per life), then active power-ups.
        drawText(`TESLA JOYRIDE · RUN ${String(runs).padStart(2, '0')}`, screenWidth - 72, 48, 34, COLOR.label, {align: 'right', spacing: 3});
        let rowsTop = 104;
        if (extraLives > 0) {
            drawText('EXTRA LIFE', screenWidth - 72, rowsTop, 40, COLOR.title, {align: 'right', spacing: 3});
            setFont(40, 3);
            const iconRight = screenWidth - 72 - ctx.measureText('EXTRA LIFE').width - 16;
            for (let index = 0; index < extraLives; index += 1) {
                ctx.drawImage(images.car_idle, iconRight - 84 * (index + 1) - 12 * index, rowsTop + 6, 84, 30);
            }
            rowsTop += 64;
        }

        // Active power-ups below that, each with the time it has left.
        const active = [
            hasShield && {kind: 'shield', fraction: 1},
            boostTime > 0 && {kind: 'boost', fraction: boostTime / POWER_UPS.boost.seconds},
            slowTime > 0 && {kind: 'slowmo', fraction: slowTime / POWER_UPS.slowmo.seconds}
        ].filter(Boolean);
        active.forEach(({kind, fraction}, index) => {
            const {label, color} = POWER_UPS[kind];
            const top = rowsTop + index * 72;
            drawText(label, screenWidth - 72, top, 40, color, {align: 'right', spacing: 3});
            fillRect(screenWidth - 312, top + 46, 240, 6, COLOR.inactive);
            fillRect(screenWidth - 312, top + 46, 240 * fraction, 6, color);
        });
        drawTimeline({left: 650 + extraX / 2, top: timelineTop, width: 640, start: 20, span: 600, isFinal: false});

        const groundY = getGroundY();
        const altitude = Math.max(0, Math.round((groundY - carY) / PX_PER_METRE));
        const hudGauge = {scale: 3, label: [40, 30], value: [66, 76], unit: [132, 26]};
        const quarter = FULL_CHARGE_METRES / 4;
        drawGauge(1440 + extraX, 856 + extraY, hudGauge, (score % quarter) / quarter, COLOR.text, 'DISTANCE', score, 'M');
        drawGauge(1440 + 192 + 40 + extraX, 856 + extraY, hudGauge, (groundY - carY) / groundY, COLOR.text, 'ALTITUDE', altitude, 'M');
    }

    function drawGameOverScreen() {
        ctx.globalAlpha = 0.4;
        fillRect(0, 0, screenWidth, screenHeight, '#000');
        ctx.globalAlpha = 1;
        const menu = getMenuOffset();
        ctx.translate(menu.x, menu.y);

        drawText('GAME OVER', BASE_WIDTH / 2, 96, 200, COLOR.title, {align: 'center', spacing: 12, shadow: 8});

        const charge = getCharge(score);
        const overGauge = {scale: 4, label: [54, 38], value: [88, 100], unit: [176, 32]};
        drawGauge(512, 316, overGauge, charge / 100, COLOR.red, 'CHARGE', charge, '%');
        drawGauge(512 + 320, 316, overGauge, score / FULL_CHARGE_METRES, COLOR.text, 'DISTANCE', score, 'M');
        drawGauge(512 + 640, 316, overGauge, bestScore / FULL_CHARGE_METRES, isNewBest ? COLOR.red : COLOR.text, 'BEST', bestScore, 'M');

        drawTimeline({left: 440, top: 584, width: 1040, start: 60, span: 920, isFinal: true});
        drawClock(BASE_WIDTH / 2, 'center', {top: 722});
        ctx.drawImage(images.btn_play, PLAY_BUTTON.x, PLAY_BUTTON.y, PLAY_BUTTON.width, PLAY_BUTTON.height);
    }

    // "T+" (64 px) and "HH:MM:SS" (120 px), baseline-aligned with a 14 px gap, line-height 0.8.
    // Place it by `top` (a CSS-style line box) or by `centerY` (the digits' visible middle).
    function drawClock(x, align, {top, centerY}) {
        const time = formatClock(elapsed);
        setFont(64, 0);
        const prefixWidth = ctx.measureText('T+').width;
        setFont(120, 4);
        const digits = ctx.measureText(time);
        const timeWidth = digits.width;
        const baseline = centerY === undefined
            ? getBaseline(top, 120, 0.8)
            : centerY + (digits.actualBoundingBoxAscent - digits.actualBoundingBoxDescent) / 2;
        const totalWidth = prefixWidth + 14 + timeWidth;
        const left = {left: x, center: x - totalWidth / 2, right: x - totalWidth}[align];

        setFont(64, 0);
        fillText('T+', left, baseline, COLOR.secondary);
        setFont(120, 4);
        fillText(time, left + prefixWidth + 14, baseline, COLOR.text);
    }

    function drawTimeline({left, top, width, start, span, isFinal}) {
        const metresX = (value) => left + start + Math.min(1, value / FULL_CHARGE_METRES) * span;
        const currentX = metresX(score);

        fillRect(left, top + TIMELINE_LINE_Y, width, 3, COLOR.track);
        fillRect(left, top + TIMELINE_LINE_Y, currentX - left, 3, COLOR.text);

        for (const node of TIMELINE_NODES) {
            const x = metresX(node.metres);
            const isReached = score >= node.metres;
            fillRect(x - 9, top + 41, 18, 18, isReached ? COLOR.text : COLOR.track);
            fillRect(x - 6, top + 44, 12, 12, COLOR.panel);
            if (isReached) fillRect(x - 3, top + 47, 6, 6, COLOR.text);
        }

        if (isFinal) {
            fillRect(currentX - 9, top + 32, 18, 35, COLOR.red);
        } else {
            fillRect(currentX - 3, top + 36, 6, 27, COLOR.red);
        }

        TIMELINE_NODES.forEach((node, index) => {
            const x = metresX(node.metres);
            // Labels alternate above/below; a lower label moves up when the crash label needs the space.
            const isAbove = index % 2 === 0 || (isFinal && Math.abs(x - currentX) < 140);
            const color = score >= node.metres ? COLOR.label : COLOR.secondary;
            drawText(node.label, x, top + (isAbove ? 0 : 76), 34, color, {align: 'center', spacing: 2});
        });

        if (isFinal) {
            drawText(`CRASH · ${score} M`, currentX, top + 76, 34, COLOR.redLight, {align: 'center', spacing: 2});
        }
    }

    function drawGauge(x, y, layout, fraction, fill, label, value, unit) {
        const {scale} = layout;
        ctx.drawImage(getGaugeImage(fraction, fill), x, y, 64 * scale, 56 * scale);
        const centerX = x + 32 * scale;
        drawText(label, centerX, y + layout.label[0], layout.label[1], COLOR.label, {align: 'center', spacing: 2});
        drawText(String(value), centerX, y + layout.value[0], layout.value[1], COLOR.text, {align: 'center', spacing: 2});
        drawText(unit, centerX, y + layout.unit[0], layout.unit[1], COLOR.secondary, {align: 'center', spacing: 2});
    }

    // ---- Pixel-art arc gauge (64×56 game px, centre 32,32, 270° sweep from bottom-left over the top) ----

    function createGaugeGeometry() {
        const pixels = [];
        for (let y = 0; y < 56; y += 1) {
            for (let x = 0; x < 64; x += 1) {
                const dx = x + 0.5 - 32;
                const dy = y + 0.5 - 32;
                const distanceFromCenter = Math.hypot(dx, dy);
                const angle = (Math.atan2(dy, dx) * 180 / Math.PI + 360) % 360;
                const sweep = ((angle - 135 + 360) % 360) / 270;
                let kind = null;
                if (distanceFromCenter < 26) kind = 'disc';
                else if (distanceFromCenter >= 31 && distanceFromCenter < 32.5) kind = 'halo';
                else if (distanceFromCenter >= 27 && distanceFromCenter < 30 && sweep <= 1) kind = sweep <= 0.025 ? 'tick' : 'ring';
                else if (distanceFromCenter >= 23 && distanceFromCenter < 27 && sweep <= 0.025) kind = 'tick';
                pixels.push({kind, sweep});
            }
        }
        return pixels;
    }

    function getGaugeImage(fraction, fill) {
        const clamped = Math.min(1, Math.max(0, fraction));
        const key = `${fill}:${clamped.toFixed(3)}`;
        if (gaugeCache.has(key)) return gaugeCache.get(key);

        const gauge = document.createElement('canvas');
        gauge.width = 64;
        gauge.height = 56;
        const gaugeContext = gauge.getContext('2d');
        const data = gaugeContext.createImageData(64, 56);
        const colors = {
            disc: [0, 0, 0, 128],
            halo: [0, 0, 0, 115],
            tick: [...hexToRgb(COLOR.text), 255],
            fill: [...hexToRgb(fill), 255],
            empty: [...hexToRgb(COLOR.inactive), 255]
        };

        gaugeGeometry.forEach(({kind, sweep}, index) => {
            if (!kind) return;
            const color = kind === 'ring' ? (sweep <= clamped ? colors.fill : colors.empty) : colors[kind];
            data.data.set(color, index * 4);
        });
        gaugeContext.putImageData(data, 0, 0);
        gaugeCache.set(key, gauge);
        return gauge;
    }

    function hexToRgb(hex) {
        const value = Number.parseInt(hex.slice(1), 16);
        return [value >> 16, (value >> 8) & 255, value & 255];
    }

    // ---- Text helpers (positions follow CSS: `top` is the top of a line box with the given line-height) ----

    function drawText(text, x, top, size, color, {align = 'left', spacing = 0, shadow = 0, lineHeight = 1} = {}) {
        const baseline = getBaseline(top, size, lineHeight);
        setFont(size, spacing, align);
        if (shadow) fillText(text, x + shadow, baseline + shadow, '#000');
        fillText(text, x, baseline, color);
        ctx.textAlign = 'left';
    }

    function getBaseline(top, size, lineHeight) {
        const {ascent, descent} = getFontMetrics(size);
        return top + (size * lineHeight - (ascent + descent)) / 2 + ascent;
    }

    function getFontMetrics(size) {
        setFont(size, 0);
        const metrics = ctx.measureText('M');
        return {ascent: metrics.fontBoundingBoxAscent ?? size * 0.8, descent: metrics.fontBoundingBoxDescent ?? size * 0.2};
    }

    function setFont(size, spacing, align = 'left') {
        ctx.font = `${size}px ${FONT}`;
        ctx.letterSpacing = `${spacing}px`;
        ctx.textAlign = align;
        ctx.textBaseline = 'alphabetic';
    }

    function fillText(text, x, y, color) {
        ctx.fillStyle = color;
        ctx.fillText(text, x, y);
    }

    function fillRect(x, y, width, height, color) {
        ctx.fillStyle = color;
        ctx.fillRect(x, y, width, height);
    }

    // ---- Input: press starts a run, holding fires the thrusters, release lets the car fall ----

    function handlePointerDown(event) {
        if (event.button !== 0 || event.target.closest?.(UI_SELECTOR)) return;
        event.preventDefault();
        press(() => isOnPlayButton(event));
    }

    function handleKeyDown(event) {
        if (!GAME_KEYS.includes(event.code) || event.target.closest?.(UI_SELECTOR)) return;
        event.preventDefault();
        if (event.repeat) return;
        press(() => true);
    }

    function handleKeyUp(event) {
        if (GAME_KEYS.includes(event.code)) releaseThrust();
    }

    function press(isRestartTarget) {
        if (state === State.READY) {
            isThrusting = true;
            startGame();
        } else if (state === State.PLAYING) {
            isThrusting = true;
        } else if (canRestart() && isRestartTarget()) {
            showStartScreen();
        }
    }

    function releaseThrust() {
        isThrusting = false;
    }

    // A long press on a phone would otherwise open the browser menu mid-flight.
    function preventContextMenu(event) {
        if (!event.target.closest?.(UI_SELECTOR)) event.preventDefault();
    }

    function isOnPlayButton(event) {
        const rect = canvas.getBoundingClientRect();
        const menu = getMenuOffset();
        const x = (event.clientX - rect.left) * screenWidth / rect.width - menu.x;
        const y = (event.clientY - rect.top) * screenHeight / rect.height - menu.y;
        return x >= PLAY_BUTTON.x && x <= PLAY_BUTTON.x + PLAY_BUTTON.width
            && y >= PLAY_BUTTON.y && y <= PLAY_BUTTON.y + PLAY_BUTTON.height;
    }

    function destroy() {
        if (state === State.DESTROYED) return;

        state = State.DESTROYED;
        container.dataset.gameState = state;
        cancelAnimationFrame(frameId);
        resizeObserver?.disconnect();
        if (!resizeObserver) window.removeEventListener('resize', fitStage);
        container.removeEventListener('pointerdown', handlePointerDown);
        container.removeEventListener('contextmenu', preventContextMenu);
        window.removeEventListener('pointerup', releaseThrust);
        window.removeEventListener('pointercancel', releaseThrust);
        window.removeEventListener('blur', releaseThrust);
        document.removeEventListener('keydown', handleKeyDown);
        document.removeEventListener('keyup', handleKeyUp);
        container.classList.remove('flappy-game');
        container.removeAttribute('role');
        container.removeAttribute('aria-label');
        container.replaceChildren();
    }
}

// ---- app.js ----
function initializeGame() {
    const params = new URLSearchParams(location.search);
    const isDebug = params.get('debug') === 'true';
    const theme = params.get('theme');
    const debugCheckbox = document.getElementById('debugToggle');

    debugCheckbox.checked = isDebug;
    debugCheckbox.addEventListener('change', function handleDebugChange() {
        params.set('debug', String(this.checked));
        location.search = params.toString();
    });

    TeslaJoyride('container', {
        difficulty: 'normal', // easy | normal | hard
        ...(Object.hasOwn(THEMES, theme ?? '') && {theme}), // ?theme=night|dawn|day overrides the saved choice
        debug: isDebug
    });
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initializeGame, {once: true});
} else {
    initializeGame();
}
